def parse_version(s):
    if not s:
        return []
    parts = s.split('.')
    result = []
    for part in parts:
        if part.isdigit():
            result.append(int(part))
        else:
            try:
                result.append(int(part.rstrip('0')))
            except ValueError:
                raise ValueError(f'invalid version component: {part}')
    return result
